import subprocess, re
def file_content(path):
    return subprocess.check_output(['git','show',f'origin/main:{path}'],text=True)
# list episode files on origin/main
out=subprocess.check_output(['git','ls-tree','-r','--name-only','origin/main'],text=True)
files=[l for l in out.splitlines() if re.match(r'S\d+/E\d+\.md',l)]
sources=set()
for f in files:
    for line in file_content(f).splitlines():
        m=re.match(r'^Source: friend/(\w+) @ ([0-9a-f]{40})$',line.strip())
        if m: sources.add(m.group(2))
def is_fm(sha):
    body=subprocess.check_output(['git','log','-1','--format=%B',sha],text=True)
    return any(line.strip()=='Friend-Message: 1' for line in body.splitlines())
missing=[]
for b in ['rachel','monica','phoebe','joey','chandler','ross']:
    out=subprocess.check_output(['git','log','--format=%H',f'origin/friend/{b}'],text=True)
    for sha in out.splitlines():
        if is_fm(sha) and sha not in sources:
            # get episode
            body=subprocess.check_output(['git','log','-1','--format=%B',sha],text=True)
            ep=None
            for l in body.splitlines():
                m=re.match(r'^Episode:\s*(.+)$',l.strip())
                if m: ep=m.group(1).strip()
            missing.append((sha,b,ep))
print('missing actual:',len(missing))
for m in missing: print(m)
